//! Exposes build identity metadata (`INK_BUILD_COMMIT`, `INK_BUILD_DIRTY`, `INK_BUILD_DIFF`,
//! `INK_BUILD_LOCK`, `INK_BUILD_VENDOR`) to `ink-record`.
//!
//! If `engine/rust/BUILD_ID.json` (generated by `scripts/build-id.sh`) is present, it is read and
//! strictly validated. Otherwise, this build script derives the same fields automatically from git
//! and `Cargo.lock` so `cargo build --release --locked` works out of the box on any clean checkout.

use std::{env, fs, path::PathBuf, process::Command, process::exit};

fn fail(msg: &str) -> ! {
    eprintln!("ink-record build.rs: {msg}");
    exit(1);
}

fn is_hex(s: &str, len: usize) -> bool {
    s.len() == len && s.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
}

fn sha256_hex(data: &[u8]) -> String {
    // Standard FIPS 180-4 SHA-256 (self-contained so build.rs needs no extra crate).
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98,
        0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
        0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8,
        0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819,
        0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
        0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    ];
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];
    let bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while (msg.len() % 64) != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in msg.as_chunks::<64>().0 {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[4 * i], chunk[4 * i + 1], chunk[4 * i + 2], chunk[4 * i + 3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }
        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = h;
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        for (slot, delta) in h.iter_mut().zip([a, b, c, d, e, f, g, hh]) {
            *slot = slot.wrapping_add(delta);
        }
    }
    let mut out = String::with_capacity(64);
    for word in h {
        use std::fmt::Write;
        let _ = write!(&mut out, "{word:08x}");
    }
    out
}

fn git_cmd(ws: &PathBuf, args: &[&str]) -> Option<String> {
    let out = Command::new("git").current_dir(ws).args(args).output().ok()?;
    if !out.status.success() {
        return None;
    }
    String::from_utf8(out.stdout).ok()
}

fn main() {
    let dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("cargo sets CARGO_MANIFEST_DIR"));
    let ws = dir.join("../..");
    let path = ws.join("BUILD_ID.json");
    let lock_path = ws.join("Cargo.lock");
    println!("cargo::rerun-if-changed={}", path.display());
    println!("cargo::rerun-if-changed={}", lock_path.display());

    if let Ok(text) = fs::read_to_string(&path) {
        let id: serde_json::Value =
            serde_json::from_str(&text).unwrap_or_else(|e| fail(&format!("BUILD_ID.json: {e}")));
        let commit = id["commit"].as_str().unwrap_or_default();
        if !is_hex(commit, 40) {
            fail(&format!(
                "BUILD_ID.json: commit must be 40 lowercase hex digits, got {commit:?}"
            ));
        }
        let dirty = id["dirty"]
            .as_bool()
            .unwrap_or_else(|| fail("BUILD_ID.json: dirty must be a boolean"));
        let diff = match (&id["diff"], dirty) {
            (serde_json::Value::Null, false) => "-".to_owned(),
            (serde_json::Value::String(d), true) if is_hex(d, 64) => d.clone(),
            _ => fail("BUILD_ID.json: diff must be a sha256 hex string when dirty and null when clean"),
        };
        let hex64 = |key: &str| -> String {
            match id[key].as_str() {
                Some(h) if is_hex(h, 64) => h.to_owned(),
                _ => fail(&format!(
                    "BUILD_ID.json: {key} must be a sha256 hex string (scripts/build-id.sh)"
                )),
            }
        };
        println!("cargo::rustc-env=INK_BUILD_LOCK={}", hex64("lock"));
        println!("cargo::rustc-env=INK_BUILD_VENDOR={}", hex64("vendor"));
        println!("cargo::rustc-env=INK_BUILD_COMMIT={commit}");
        println!("cargo::rustc-env=INK_BUILD_DIRTY={}", u8::from(dirty));
        println!("cargo::rustc-env=INK_BUILD_DIFF={diff}");
        return;
    }

    // Fallback: derive build identity directly from git + Cargo.lock.
    let commit = git_cmd(&ws, &["rev-parse", "HEAD"])
        .map(|s| s.trim().to_ascii_lowercase())
        .filter(|s| is_hex(s, 40))
        .unwrap_or_else(|| "0".repeat(40));

    let dirty_out = git_cmd(&ws, &["status", "--porcelain", "--", "engine"]).unwrap_or_default();
    let dirty = !dirty_out.trim().is_empty();
    let diff = if dirty {
        let diff_bytes = git_cmd(&ws, &["diff", "HEAD", "--", "engine"]).unwrap_or_default();
        sha256_hex(diff_bytes.as_bytes())
    } else {
        "-".to_owned()
    };

    let lock = fs::read(&lock_path)
        .map(|b| sha256_hex(&b))
        .unwrap_or_else(|_| "0".repeat(64));
    let vendor = "0".repeat(64);

    println!("cargo::rustc-env=INK_BUILD_LOCK={lock}");
    println!("cargo::rustc-env=INK_BUILD_VENDOR={vendor}");
    println!("cargo::rustc-env=INK_BUILD_COMMIT={commit}");
    println!("cargo::rustc-env=INK_BUILD_DIRTY={}", u8::from(dirty));
    println!("cargo::rustc-env=INK_BUILD_DIFF={diff}");
}
